import{_ as o,o as e,c as a,ag as l}from"./chunks/framework.CAXxHpAX.js";const d=JSON.parse('{"title":"认真工作也是禅定","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/修行即生活-认真工作也是禅定.md","filePath":"60-原文段落/修行即生活-认真工作也是禅定.md","lastUpdated":1778155802000}'),_={name:"60-原文段落/修行即生活-认真工作也是禅定.md"};function r(u,t,i,c,q,n){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="认真工作也是禅定" tabindex="-1">认真工作也是禅定 <a class="header-anchor" href="#认真工作也是禅定" aria-label="Permalink to &quot;认真工作也是禅定&quot;">​</a></h1><blockquote><p>来源：修行即生活（20090111b）</p></blockquote><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><blockquote><p>&quot;其实修炼的人，我观察过很多修了很长时间没有什么成就的人，他们就是将修行和生活、工作隔离开了。他们就是每天喜欢说事情做完抓紧时间去打坐了，去练功了，去念佛了。他们就不懂得其实时时处处都是道场。工作我老是提醒同修，我说认真工作也是禅定。就是在日常生活中事事都是修行，穿衣吃饭也是修行。&quot;</p></blockquote><blockquote><p>&quot;你等一下工作做完，一盘起腿来一认认真真地念佛，本来心情就平静。这么一坐下来，一专门练功就深入境界了。那等一下一收功又去做事，又是在禅定之中做事。做完事又来练功，又是深入境界了。你每一次练功所深入禅定的境界，在日常中不容易消失。所以等于你每次练功都会觉得进步。这样提升就快了。&quot;</p></blockquote><blockquote><p>&quot;假如工作生活到处都是风风火火，到处都是神不守舍。这里心也很慌，那里心也紧张。那好，等下有空一坐下来，怎么坐都静不下去。努力地坐了半个小时、一个小时，马马虎虎能够静下来，一看时间已经过去了，腿也酸麻了。刚刚坐到有个好感觉，就已经没时间再坐下去，那个腿也受不了，坐不下去了。那好，又去工作，又去生活，把刚才得到了一点好境界马上又丢了。工作做完了，要来盘腿而坐，又会花了很大劲才能够安静下来。天天如是，这个就是竹篮打水一场空了。所以就是说生活处处是道场，真正修行人真的是一言一行，做什么事情一举一动，他都会很认真。&quot;</p></blockquote><blockquote><p>&quot;穿衣服你要认认真真地穿，不要慌张，也不要糊里糊涂慌慌张张纽扣也扣错了……吃饭，有些人吃饭也会吃到卡喉咙，不会吃鱼的人也会卡到喉咙，吃白饭都会呛着喉咙，就是因为他吃的时候不认真嘛。假如我们做每一件事情又要做得快，又要保持很专注。那可以说整天都在禅定之中。&quot;</p></blockquote><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to &quot;关键要点&quot;">​</a></h2><ul><li>认真工作本身就是禅定，不是工作之余才&quot;抽空修行&quot;</li><li>工作生活风风火火→静坐时难入静→好境界马上丢掉→竹篮打水一场空</li><li>工作认真做→心本来平静→一坐下来深入境界→收功又禅定做事→良性循环</li><li>穿衣吃饭都要认认真真，专注就是禅定</li></ul>',9)])])}const p=o(_,[["render",r]]);export{d as __pageData,p as default};
